const storyData={gandhi:{heroTitle:"Path of Non-Violence",heroColor:"var(--primary-saffron)",events:[{year:"1915",title:"The Return",desc:"Mahatma Gandhi returns to India from South Africa, bringing with him the philosophy of Satyagraha (truth-force) and non-violent resistance."},{year:"1917",title:"Champaran Satyagraha",desc:"The first major civil disobedience movement. Gandhi organizes impoverished farmers against oppressive British indigo planters, securing a major victory."},{year:"1920",title:"Non-Cooperation Movement",desc:"A nationwide campaign to boycott British goods, courts, and educational institutions. Millions of Indians surrender their British titles and jobs."},{year:"1930",title:"The Salt March (Dandi March)",desc:"A 240-mile march to the Arabian Sea to protest the British salt monopoly. Gandhi boils seawater to make salt, awakening the world's conscience."},{year:"1942",title:"Quit India Movement",desc:"The final, decisive call for the British to leave India immediately with the legendary slogan: 'Do or Die'."}]},bhagat:{heroTitle:"Path of Revolution",heroColor:"var(--primary-gold)",events:[{year:"1919",title:"Jallianwala Bagh Massacre",desc:"A 12-year-old Bhagat Singh visits the blood-stained grounds of Jallianwala Bagh, deeply impacting him and sparking his revolutionary fire."},{year:"1926",title:"Naujawan Bharat Sabha",desc:"Bhagat Singh founds a socialist youth organization to encourage political revolution and secularism against British rule."},{year:"1928",title:"Avenging Lala Lajpat Rai",desc:"Following the brutal death of senior leader Lala Lajpat Rai during a lathi charge, Singh and his comrades assassinate British officer John Saunders."},{year:"1929",title:"Assembly Bombing",desc:"To 'make the deaf hear', Singh and Batukeshwar Dutt throw harmless smoke bombs in the Central Legislative Assembly and surrender voluntarily, using their trial to publicize their cause."},{year:"1931",title:"Martyrdom",desc:"Bhagat Singh is hanged at the age of 23, kissing the rope with a smile. He becomes an eternal symbol of youth sacrifice and uncompromising revolution."}]},bose:{heroTitle:"Path of Armed Struggle",heroColor:"var(--primary-green)",events:[{year:"1921",title:"Resignation from ICS",desc:"Subhas Chandra Bose resigns from the highly prestigious Indian Civil Service in London, refusing to serve the British, and returns to join the freedom struggle."},{year:"1939",title:"INC Presidency",desc:"Elected president of the Indian National Congress against Gandhi's preferred candidate, Bose eventually resigns due to ideological differences regarding radical, immediate action."},{year:"1941",title:"The Great Escape",desc:"Placed under house arrest by the British, Bose miraculously escapes India in disguise, traveling through Afghanistan and Russia to seek international alliances."},{year:"1943",title:"Indian National Army (INA)",desc:"Bose takes charge of the INA in Singapore, raising a massive army of Indian POWs and civilians with the legendary call: 'Give me blood, and I shall give you freedom!'"},{year:"1944",title:"March to Delhi",desc:"The INA successfully hoists the Indian tricolor in the Andaman Islands and parts of Manipur, engaging in direct, fierce military clashes with British forces."}]}};let currentPath=null,currentEventIndex=-1;document.addEventListener("app:route-changed",()=>{const e=document.getElementById("crossroads-screen"),t=document.getElementById("journey-screen"),a=document.querySelectorAll(".path-card"),i=document.getElementById("journey-title"),n=document.getElementById("interactive-timeline"),r=document.getElementById("btn-next-event"),s=document.getElementById("btn-reset-story");e&&t&&(a.forEach(a=>{a.addEventListener("click",()=>{currentPath=a.getAttribute("data-path"),currentEventIndex=-1,function(){const a=storyData[currentPath];i.innerText=a.heroTitle,i.style.color=a.heroColor,n.innerHTML="",r.style.display="inline-flex",r.innerText="Unlock First Event",e.classList.remove("active"),setTimeout(()=>{e.classList.add("hidden"),t.classList.remove("hidden"),setTimeout(()=>t.classList.add("active"),50)},500)}()})}),r.addEventListener("click",function(){const e=storyData[currentPath];if(currentEventIndex++,currentEventIndex<e.events.length){const t=e.events[currentEventIndex],a=document.createElement("div");a.className="timeline-event locked",a.style.borderLeftColor=e.heroColor,a.innerHTML=`\n                <div class="event-year" style="color: ${e.heroColor}">${t.year}</div>\n                <div class="event-content">\n                    <h3>${t.title}</h3>\n                    <p>${t.desc}</p>\n                </div>\n            `,n.appendChild(a),setTimeout(()=>{a.classList.remove("locked"),a.classList.add("unlocked"),window.scrollTo({top:document.body.scrollHeight,behavior:"smooth"})},50),r.innerText="Unlock Next Event",currentEventIndex===e.events.length-1&&(r.style.display="none")}}),s.addEventListener("click",()=>{t.classList.remove("active"),setTimeout(()=>{t.classList.add("hidden"),e.classList.remove("hidden"),setTimeout(()=>e.classList.add("active"),50)},500)}))});